{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin, a retinoid with the same conjugated tetraene cyclohexene scaffold as the query, has a systemic bioavailability of 40% at 1 mg/kg/day, supporting F>=20% for the closely related retinoid amide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Acitretin, a retinoid acid, has an absolute oral bioavailability of approximately 60% (range 36-95%) after a 50 mg oral dose with food, demonstrating that highly lipophilic retinoids can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Etretinate, a neutral, highly lipophilic retinoid ester, has an absolute bioavailability of about 40% in healthy volunteers, supporting that the query's neutral amide retinoid can also achieve F>=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Paracetamol, which shares the p-hydroxyanilide substructure with the query, has an absolute oral bioavailability of about 82%, indicating that the phenol/amide moiety is not inherently a barrier to F>=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "One report describes 13-cis-retinoic acid as having low absolute bioavailability due to gut degradation and metabolism, providing a caution that some retinoid formulations can fall below the threshold, but this is formulation/acid-specific.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is fenretinide, a lipophilic retinoid amide. Closely related retinoids (isotretinoin, acitretin, etretinate) consistently show absolute oral bioavailability of 40-60%, all above the 20% threshold. The p-hydroxyanilide substructure is also present in paracetamol, which has high oral bioavailability. Although solubility is poor and some retinoid formulations show erratic absorption, the weight of transferable evidence supports F>=20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fenretinide in humans or animals was provided.",
    "The impact of the phenolic group on first-pass glucuronidation/sulfation in the context of the large retinoid amide is not directly quantified.",
    "Formulation and food effects, which are critical for lipophilic retinoids, are not specified for the query.",
    "Conflicting reports for retinoic acid isomers (low/erratic vs 40-50%) create uncertainty in extrapolation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

